import { BlockAssembler, isAgentLoopRequest } from '@deepseek-ai/dsh-llm';

/** Only the real agent loop is intercepted; recall/review/other auxiliary calls pass through. */
export function attachAgentFilter(ctx, filter) {
    const admissions = new WeakMap();
    ctx.on('session/event', (session, event) => {
        if (event.type === 'turn/end') filter.resetTurn(`${session.id}:${event.data.turn}`);
    });
    ctx.on('agent/pre-step', async ({ agent, turn, signal, messages }, next) => {
        const previous = admissions.get(signal);
        const human = messages.filter(message => message.role === 'user' && message.source?.kind === 'user').at(-1);
        const userText = human
            ? human.content.filter(block => block.type === 'text').map(block => block.text).join('\n')
            : previous?.agent === agent && previous.turn === turn ? previous.userText : '';
        admissions.set(signal, { agent, turn, userText });
        return next();
    });
    ctx.on('llm/stream', (request, next) => {
        if (!isAgentLoopRequest(request)) return next();
        const admission = admissions.get(request.signal);
        if (!admission || admission.agent.session.id !== request.sessionId) return next();
        return filteredStream(next(), request, admission, ctx, filter);
    });
}

async function* filteredStream(stream, request, { agent, turn, userText }, ctx, filter) {
    // Nine passes operate on sentences, not tokens. Nothing unfiltered reaches
    // assistant-stream or assistant/message (both are downstream of this hook).
    const chunks = [];
    const assembled = new BlockAssembler();
    const textIndices = new Set();
    for await (const chunk of stream) {
        request.signal.throwIfAborted();
        chunks.push(chunk);
        assembled.push(chunk);
        if (chunk.type === 'text-delta' ||
            (chunk.type === 'block-start' && chunk.blockType === 'text') ||
            (chunk.type === 'block-end' && chunk.block.type === 'text')) textIndices.add(chunk.index);
    }
    request.signal.throwIfAborted();
    // Failures retain their exact protocol and are never turned into success.
    if (assembled.finish.kind === 'error' || assembled.finish.kind === 'aborted' || textIndices.size === 0) {
        yield* chunks;
        return;
    }
    const text = assembled.blocks().filter(block => block.type === 'text').map(block => block.text).join('\n');
    const recent = request.messages.filter(message => message.role === 'assistant')
        .map(message => message.content.filter(block => block.type === 'text').map(block => block.text).join('\n'));
    const safetyMode = ctx.get('ondra-crisis')?.forAgent(agent)?.holdRoleplay === true;
    const relation = ctx.get('ondra-persona-core')?.stats().relation;
    const result = filter.run({ text, recent, relation, safetyMode, userText });
    if (result.needsRegenerate) {
        // Core has no replace-assistant/pre-commit hook. Do not invent a reply,
        // emit empty success, or retry tools behind the loop's back.
        const error = new Error('输出过滤后没有可发送正文，需要重新生成');
        error.code = 'ONDRA_FILTER_REGENERATE_REQUIRED';
        throw error;
    }
    // Optional review is explicitly bounded per agent turn, never the shared
    // "default" bucket. Its own documented degraded/error handling is retained.
    const turnId = `${agent.session.id}:${turn}`;
    // The normal review grades persona style and brevity. Urgent safety guidance
    // must not be steered back into roleplay (the crisis guard explicitly holds it).
    const review = safetyMode ? { verdict: 'pass' } : await filter.review({ text: result.text, userText, turnId });
    request.signal.throwIfAborted();
    if (review.verdict === 'steer') {
        const error = new Error(`输出评审要求重新生成：${review.feedback}`);
        error.code = 'ONDRA_FILTER_REVIEW_REQUIRED';
        throw error;
    }
    let emitted = false;
    const changed = result.text !== text || textIndices.size > 1;
    for (const chunk of chunks) {
        if ('index' in chunk && textIndices.has(chunk.index)) {
            if (!emitted) {
                emitted = true;
                yield { type: 'block-start', index: chunk.index, blockType: 'text' };
                yield { type: 'text-delta', index: chunk.index, text: result.text };
                yield { type: 'block-end', index: chunk.index, block: { type: 'text', text: result.text } };
            }
            continue;
        }
        // Opaque provider replay state describes the original blocks. Keeping it
        // after editing could replay the unfiltered response on the next turn.
        if (changed && chunk.type === 'finish') {
            const { replayState, ...finish } = chunk;
            yield finish;
        } else yield chunk;
    }
}
